export type VaultMarkType = 1 | 2 | 3 | 4 | 5;
export type VaultQuestionType = "MCQ" | "VSA" | "SA" | "LA" | "Proof" | "Case Study";

export interface VaultQuestion {
  id: string;
  chapter: number;
  chapterName: string;
  marks: VaultMarkType;
  type: VaultQuestionType;
  question: string;
  options?: string[];
  correctOption?: number;
  answer: string;
  steps?: string[];          // step-by-step solution
  explanation?: string;
  formula?: string;         // key formula used
  examinerNote?: string;
  source?: string;          // KVS / NCERT / RD Sharma / Board PYQ
  diagramSvg?: string;      // Visual SVG circuit or optics diagram
  diagramImageUrl?: string; // High-res image diagram (/study_material/...)
}

export interface VaultChapterInfo {
  chapter: number;
  chapterName: string;
  emoji: string;
  accentColor: string;
  theoryBlocks: {
    title: string;
    content: string;
    formula?: string;
  }[];
  topTraps: string[];
  keyFormulas: { name: string; expr: string }[];
}

