    type: "SA",
    question: `Let △ABC ~ △DEF and their areas be 25 cm² and 121 cm² respectively. 
If AB = 5 cm, find the length of the corresponding side DE.`,
    answer: `DE = 11 cm`,
    steps: [
      `### Given:`,
      `△ABC ~ △DEF`,
      `Area of △ABC = 25 cm²`,
      `Area of △DEF = 121 cm²`,
      `AB = 5 cm`,
      `### To find:`,
      `Length of DE`,
      `### Solution:`,
      `Since △ABC ~ △DEF,`,
      `By the theorem of ratio of areas of similar triangles,`,
      `Area of △ABC        AB²`,
      `──────────────  =  ─────`,
      `Area of △DEF        DE²`,
      `Substituting the given values,`,
      `25             5²`,
      `─────       =   ─────`,
      `121             DE²`,
      `25             25`,
      `─────       =   ─────`,
      `121             DE²`,
      `Cross-multiplying,`,
      `25 × DE² = 121 × 25`,
      `DE² = (121 × 25) / 25`,
      `DE² = 121`,
      `Taking the square root on both sides,`,
      `DE = √121`,
      `DE = 11 cm`,
      `Therefore, the length of DE is 11 cm.`,
    ],
    source: "RD Sharma / Master Prompt"
