    id: "tri_master_150",
    chapter: 6,
    chapterName: "Triangles",
    marks: 5,
    type: "SA",
    question: `A vertical pole of length 1 m casts a shadow 6 m long on the ground. 
At the same time, a tower casts a shadow 30 m long. Find the height of the tower.`,
    answer: `Height of the tower = 5 m`,
    steps: [
      `### Given:`,
      `Height of the pole (AB) = 1 m`,
      `Shadow of the pole (BC) = 6 m`,
      `Shadow of the tower (QR) = 30 m`,
      `Let the height of the tower be PQ = h m.`,
      `### To find:`,
      `Height of the tower (PQ)`,
      `### Solution:`,
      `Let △ABC represent the pole and its shadow, and △PQR represent the tower and its shadow.`,
      `In △ABC and △PQR,`,
      `The angle of elevation of the sun is the same for both at the same time.`,
      `∠C = ∠R  (Angular elevation of the Sun)`,
      `∠B = ∠Q = 90°  (Both pole and tower are vertical to the ground)`,
      `Therefore,`,
      `△ABC ~ △PQR  (By AA similarity criterion)`,
      `Since the corresponding sides of similar triangles are proportional,`,
      `AB       PQ`,
      `─────  =  ─────`,
      `BC       QR`,
      `Substituting the given values,`,
      `1        h`,
      `─────  =  ─────`,
      `6       30`,
      `Cross-multiplying,`,
      `6 × h = 1 × 30`,
      `6 × h = 30`,
      `h = 30 / 6`,
      `h = 5 m`,
      `Therefore, the height of the tower is 5 m.`,
    ],
    source: "RD Sharma / Master Prompt"
